<?php $categoryLabels = ['Promocion de la salud' => 'Promoción de la salud', 'Prevencion de accidentes' => 'Prevención de accidentes', 'Prevencion de enfermedad laboral' => 'Prevención de enfermedad laboral', 'Vigilancia epidemiologica' => 'Vigilancia epidemiológica']; $totalActivities=0; $completedActivities=0; foreach ($programs as $item) { $totalActivities += (int) $item['total_actividades']; $completedActivities += (int) $item['actividades_completadas']; } ?>
<div class="page-heading"><div><span class="eyebrow">Promoción · Prevención · Vigilancia</span><h1>Programas de promoción y prevención</h1><p>Intervenciones basadas en diagnóstico, con objetivos, actividades, recursos, metas y evidencias.</p></div><a href="<?= e(url('/programas-prevencion/nuevo')) ?>" class="btn-primary"><?= icon('plus', 'h-4 w-4') ?> Nuevo programa</a></div>
<div class="mt-5 rounded-2xl bg-blue-50 p-4 text-[11px] leading-5 text-blue-800 ring-1 ring-blue-100">Selecciona los programas según los peligros priorizados, las condiciones de salud, la accidentalidad y los requisitos aplicables. Una plantilla o la aprobación del documento no reemplaza su implementación ni la evaluación de eficacia.</div>
<section class="mt-6 grid grid-cols-3 gap-3"><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Programas en la vista</p><p class="mt-2 text-2xl font-semibold"><?= count($programs) ?></p></div><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Actividades registradas</p><p class="mt-2 text-2xl font-semibold"><?= $totalActivities ?></p></div><div class="ios-card p-4"><p class="text-[11px] text-slate-400">Actividades completadas</p><p class="mt-2 text-2xl font-semibold text-emerald-600"><?= $completedActivities ?></p></div></section>
<section class="ios-card mt-6 overflow-hidden"><div class="card-heading"><div><h2>Portafolio preventivo</h2><p>Documentos controlados y seguimiento operativo.</p></div><form method="get" action="<?= e(url('/programas-prevencion')) ?>" class="flex flex-wrap gap-2"><select name="anio" class="input h-9 !w-auto text-xs"><option value="">Todos los años</option><?php foreach ($years as $year): ?><option value="<?= (int) $year ?>"<?= selected($filters['anio'], $year) ?>><?= (int) $year ?></option><?php endforeach; ?></select><select name="categoria" class="input h-9 !w-auto text-xs"><option value="">Todas las categorías</option><?php foreach ($categories as $category): ?><option value="<?= e($category) ?>"<?= selected($filters['categoria'], $category) ?>><?= e($categoryLabels[$category]) ?></option><?php endforeach; ?></select><button class="btn-secondary h-9" type="submit">Filtrar</button></form></div>
<?php if ($programs === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('phva', 'h-7 w-7') ?></span><h3>No hay programas en esta vista</h3><p>Crea un programa a partir del diagnóstico o cambia los filtros.</p></div><?php else: ?><div class="grid gap-4 p-5 lg:grid-cols-2"><?php foreach ($programs as $program): ?><?php $total=(int)$program['total_actividades']; $done=(int)$program['actividades_completadas']; $progress=$total>0?(int)round($done/$total*100):0; ?><article class="rounded-2xl border border-slate-100 p-5 transition hover:shadow-ios"><div class="flex items-start justify-between gap-3"><span class="badge badge-blue"><?= e($categoryLabels[$program['categoria']]) ?></span><span class="badge <?= status_class($program['estado']) ?>"><?= e($program['estado']) ?></span></div><p class="mt-4 font-mono text-[10px] font-semibold text-blue-600"><?= e($program['codigo']) ?> · <?= (int) $program['anio'] ?> · v<?= (int) $program['version'] ?></p><h3 class="mt-2 text-sm font-semibold leading-6 text-slate-800"><?= e($program['nombre']) ?></h3><p class="mt-2 text-xs leading-5 text-slate-500"><?= e(excerpt($program['objetivo_general'], 130)) ?></p><div class="mt-5"><div class="mb-1.5 flex justify-between text-[11px]"><span class="text-slate-400"><?= $done ?> de <?= $total ?> actividades</span><strong><?= $progress ?>%</strong></div><div class="progress-track"><span class="bg-emerald-500" style="width: <?= $progress ?>%"></span></div></div><div class="mt-5 flex items-center justify-between"><p class="text-[11px] text-slate-400"><?= e($program['responsable']) ?></p><a href="<?= e(url('/programas-prevencion/' . $program['id'])) ?>" class="text-link">Gestionar <?= icon('arrow-right', 'h-3.5 w-3.5') ?></a></div></article><?php endforeach; ?></div><?php endif; ?></section>
